mapper.select:
select * from tj_sic
where year=#{year}
  and month=#{month}
  and var_model in (
      concat(#{year}, '_BACC'),
      concat(#{year}, '_per_BACC'),
      concat(#{year}, '_RMSE'),
      concat(#{year}, '_per_RMSE')
  )
order by cast(day as decimal), id

SELECT DISTINCT month FROM tj_sic 
WHERE year = #{year} 
ORDER BY CAST(month AS DECIMAL)

SELECT DISTINCT day FROM tj_sic
WHERE year = #{year} AND month = #{month}
ORDER BY CAST(day AS DECIMAL)
